namespace sv_a9029a87f1a34eb89b982e3f2c444c81.Services;

public class DoctorInfo
{
    public string Name { get; set; } = string.Empty;
    public bool AcceptsSelfPay { get; set; }
}

public class ValidationResult
{
    public bool IsValid => FieldErrors.Count == 0;
    public Dictionary<string, string> FieldErrors { get; set; } = new();
}

public interface IAppointmentService
{
    Task<List<DoctorInfo>> GetDoctorsAsync();
    Task<List<string>> GetAvailableTimeSlotsAsync(string doctorName, DateOnly date);
    Task<ValidationResult> ValidatePatientAsync(string email, string insuranceProvider, string doctorName, string timeSlot);
}

public class AppointmentService : IAppointmentService
{
    private static readonly List<DoctorInfo> Doctors =
    [
        new() { Name = "Dr. Smith", AcceptsSelfPay = false },
        new() { Name = "Dr. Johnson", AcceptsSelfPay = true },
        new() { Name = "Dr. Williams", AcceptsSelfPay = true },
        new() { Name = "Dr. Brown", AcceptsSelfPay = false },
    ];

    private static readonly List<string> AllSlots =
    [
        "9:00 AM", "9:30 AM", "10:00 AM", "10:30 AM",
        "11:00 AM", "11:30 AM", "1:00 PM", "1:30 PM",
        "2:00 PM", "2:30 PM", "3:00 PM", "3:30 PM",
    ];

    public Task<List<DoctorInfo>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<DoctorInfo>(Doctors));
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctorName, DateOnly date)
    {
        // Stub: return all slots regardless of doctor/date
        return Task.FromResult(new List<string>(AllSlots));
    }

    public Task<ValidationResult> ValidatePatientAsync(
        string email, string insuranceProvider, string doctorName, string timeSlot)
    {
        var result = new ValidationResult();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.FieldErrors["Email"] = "Account has outstanding balance";
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctorName, "Dr. Smith", StringComparison.Ordinal))
        {
            result.FieldErrors["PreferredDoctor"] = "Selected doctor does not accept self-pay patients";
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            result.FieldErrors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(result);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_a9029a87f1a34eb89b982e3f2c444c81.Services
@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1: Patient Information ───── *@
    <fieldset class="mb-4">
        <legend>Step 1: Patient Information</legend>

        <div class="mb-3">
            <label for="patientName" class="form-label">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.TryGetValue("Email", out var emailError))
            {
                <div class="validation-message">@emailError</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone" class="form-label">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label for="insurance" class="form-label">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ───── STEP 2: Appointment Details ───── *@
    @if (showStep2)
    {
        <fieldset class="mb-4">
            <legend>Step 2: Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor" class="form-label">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.PreferredDoctor"
                    @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc.Name">@doc.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.PreferredDoctor" />
                @if (serverErrors.TryGetValue("PreferredDoctor", out var doctorError))
                {
                    <div class="validation-message">@doctorError</div>
                }
            </div>

            <div class="mb-3">
                <label for="date" class="form-label">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                    @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label for="timeslot" class="form-label">Time Slot</label>
                <InputSelect id="timeslot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.TryGetValue("TimeSlot", out var slotError))
                {
                    <div class="validation-message">@slotError</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability" disabled="@isSubmitting">
                Check Availability
            </button>
            <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || isSubmitting)">
                Book Appointment
            </button>
        </fieldset>
    }

    @if (bookingConfirmed)
    {
        <div class="alert alert-success mt-3">
            Appointment booked successfully!
        </div>
    }
</EditForm>

@code {
    private AppointmentFormModel Model { get; set; } = new();

    private bool showStep2;
    private bool availabilityChecked;
    private bool isSubmitting;
    private bool bookingConfirmed;

    private List<DoctorInfo> doctors = new();
    private List<string> availableSlots = new();
    private Dictionary<string, string> serverErrors = new();

    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step-1 fields manually
        editContext = new EditContext(Model);
        var validationMessageStore = new ValidationMessageStore(editContext);
        var step1Valid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
            step1Valid = false;
        if (string.IsNullOrWhiteSpace(Model.Email) || !IsValidEmail(Model.Email))
            step1Valid = false;
        if (string.IsNullOrWhiteSpace(Model.Phone))
            step1Valid = false;
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
            step1Valid = false;

        if (step1Valid)
        {
            showStep2 = true;
            availabilityChecked = false;
            serverErrors.Clear();
        }
        // If invalid, DataAnnotationsValidator on the EditForm will show messages
        // Trigger a full form validation to surface messages
        editContext.Validate();
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        serverErrors.Clear();

        if (!string.IsNullOrEmpty(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.PreferredDoctor, DateOnly.FromDateTime(Model.AppointmentDate.Value));
            Model.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityChecked = false;

        var result = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.PreferredDoctor ?? string.Empty,
            Model.TimeSlot ?? string.Empty);

        if (!result.IsValid)
        {
            serverErrors = result.FieldErrors;
            return;
        }

        availabilityChecked = true;
    }

    private async Task HandleSubmit()
    {
        if (!availabilityChecked)
            return;

        isSubmitting = true;

        // Re-validate server-side before final booking
        var result = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.PreferredDoctor ?? string.Empty,
            Model.TimeSlot ?? string.Empty);

        if (!result.IsValid)
        {
            serverErrors = result.FieldErrors;
            availabilityChecked = false;
            isSubmitting = false;
            return;
        }

        // Stub: booking succeeds
        bookingConfirmed = true;
        isSubmitting = false;
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_a9029a87f1a34eb89b982e3f2c444c81.Models;

public class AppointmentFormModel : IValidatableObject
{
    [Required(ErrorMessage = "Patient name is required.")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Enter a valid email address.")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone number is required.")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string InsuranceProvider { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a doctor.")]
    public string? PreferredDoctor { get; set; }

    [Required(ErrorMessage = "Appointment date is required.")]
    public DateTime? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string? ReasonForVisit { get; set; }

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        if (AppointmentDate.HasValue && AppointmentDate.Value.Date <= DateTime.Today)
        {
            yield return new ValidationResult(
                "Appointment date must be in the future.",
                [nameof(AppointmentDate)]);
        }
    }
}

